 const duration=s=>s==null?'–':`${s<0?'−':''}${Math.floor(Math.abs(s)/3600)}:${String(Math.floor(Math.abs(s)%3600/60)).padStart(2,'0')}`;
 const labels={pending:'Genehmigung ausstehend',awaiting_employee:'Deine Bestätigung erforderlich',approved:'Genehmigt',rejected:'Abgelehnt',closed:'Abgeschlossen',unresolved:'Stempelung klären',superseded:'Bitte neu prüfen und direkt speichern',unconfigured:'Arbeitszeitmodell fehlt',planned:'Geplant',provisional:'Vorläufig'};
 let context=null,booted=false,booting=false,reportMonth=month(),calendarMode=localStorage.getItem('pz-calendar-mode')||'month',calendarDate=today(),selectedPerson='',trackingDay=today(),trackingMode='week',trackingTab='stamps',trackingUser='',trackingTimer=null,calendarTypes=new Set(['work','pause','project','absence','duty','holiday']),generation=0;
 let contextVersion=0,loadedContextVersion=-1,contextLoading=null;
 async function loadContext(){if(context&&loadedContextVersion===contextVersion)return context;if(contextLoading)return contextLoading;const version=contextVersion;contextLoading=api('context').then(value=>{context=value;loadedContextVersion=version;return value;});try{return await contextLoading;}finally{contextLoading=null;}}
 document.addEventListener('pz-data-changed',e=>{if(!e.detail?.path||/\/(admin|customers|company|work-models)\//.test(e.detail.path))contextVersion++;});
 document.addEventListener('pz-admin-context',()=>contextVersion++);
 function person(id){const p=context?.people.find(x=>x.id===Number(id));return p?(p.last_name||p.first_name?`${p.last_name||''}, ${p.first_name||''}`:p.username):String(id);}
 function may(key){return context?.permissions.includes(key);}
 function peopleOptions(){return context.people.map(p=>`<option value="${p.id}">${h(person(p.id))}</option>`).join('');}
 function view(name,title){let v=q('#view-'+name);if(!v){v=document.createElement('section');v.id='view-'+name;v.className='view company-view';q('main').insertBefore(v,q('#toast'));}v.dataset.companyTitle=title;return v;}
